(async () => {
  try {
    await main();
    figma.notify("Conkat: arquivo de marca montado.");
  } catch (e) {
    figma.notify("Conkat: erro — " + (e && e.message ? e.message : e), { error: true, timeout: 10000 });
    log(e && e.stack ? e.stack : String(e));
    throw e;
  } finally {
    if (!IS_SCRIPTER) figma.closePlugin();
  }
})();

async function main() {
  for (const [family, style] of [
    ["Inter", "Regular"], ["Inter", "Medium"], ["Inter", "Semi Bold"], ["Inter", "Bold"],
    ["Schibsted Grotesk", "SemiBold"],
  ]) await figma.loadFontAsync({ family, style });

  const hex = (h) => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });

  // -------------------------------------------------------------------------
  // Cores (variáveis)
  // -------------------------------------------------------------------------
  const COLORS = [
    ["ink", "#0B2B2A", "Fundo escuro da marca, texto da logo"],
    ["inkSoft", "#123B39", "Superfícies sobre o fundo escuro"],
    ["background", "#F8F9FA", "Fundo claro das telas e do site"],
    ["surface", "#FFFFFF", "Cards, folhas e campos"],
    ["text", "#1A1A1A", "Texto principal"],
    ["textMuted", "#6B7280", "Texto de apoio"],
    ["brand", "#0F928C", "Marca e ícones grandes"],
    ["primary", "#0B7A75", "Ação: botões, links, aba ativa"],
    ["primarySoft", "#E6F4F3", "Fundo suave da cor de ação"],
    ["accent", "#FDA333", "Destaque pontual, sempre com texto escuro"],
    ["accentText", "#A85A00", "Laranja como texto sobre fundo claro"],
    ["accentSoft", "#FFF3E0", "Fundo suave do destaque"],
    ["border", "#E5E7EB", "Bordas e divisórias"],
    ["success", "#15803D", "Confirmação"],
    ["danger", "#B91C1C", "Erro e ação destrutiva"],
  ];
  let col = (await figma.variables.getLocalVariableCollectionsAsync()).find((c) => c.name === "Conkat / Cores");
  if (!col) col = figma.variables.createVariableCollection("Conkat / Cores");
  const mode = col.modes[0].modeId; col.renameMode(mode, "Claro");
  const existing = {}; for (const v of await figma.variables.getLocalVariablesAsync("COLOR")) existing[v.name] = v;
  const V = {};
  for (const [k, h] of COLORS) {
    const name = "cor/" + k;
    const v = existing[name] || figma.variables.createVariable(name, col, "COLOR");
    v.setValueForMode(mode, hex(h));
    v.scopes = k.startsWith("text") ? ["TEXT_FILL"] : ["FRAME_FILL", "SHAPE_FILL", "STROKE_COLOR", "TEXT_FILL"];
    V[k] = v;
  }
  const pv = (k) => figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", V[k]);

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------
  const AL = (dir, props = {}) => { const f = figma.createFrame(); f.layoutMode = dir; f.primaryAxisSizingMode = "AUTO"; f.counterAxisSizingMode = "AUTO"; f.fills = []; f.clipsContent = false; Object.assign(f, props); return f; };
  const pad = (f, t, r, b, l) => { f.paddingTop = t; f.paddingRight = r; f.paddingBottom = b; f.paddingLeft = l; return f; };
  const fill = (p, c) => { p.appendChild(c); c.layoutSizingHorizontal = "FILL"; if (c.type === "TEXT") c.textAutoResize = "HEIGHT"; return c; };
  const txt = (s, size, style = "Regular", color = "text", family = "Inter") => {
    const t = figma.createText(); t.fontName = { family, style }; t.characters = s; t.fontSize = size;
    t.lineHeight = { unit: "PERCENT", value: 140 }; t.fills = [pv(color)]; return t;
  };
  const title = (s) => { const t = txt(s, 40, "SemiBold", "text", "Schibsted Grotesk"); t.letterSpacing = { unit: "PERCENT", value: -2 }; t.lineHeight = { unit: "PERCENT", value: 115 }; return t; };
  const svgNode = (svg, h, name) => { const n = figma.createNodeFromSvg(svg); n.name = name; n.rescale(h / n.height); return n; };
  const recolor = (node, map) => {
    for (const n of node.findAll((n) => "fills" in n && Array.isArray(n.fills) && n.fills.length)) {
      const f = n.fills[0]; if (f.type !== "SOLID") continue;
      const key = [f.color.r, f.color.g, f.color.b].map((c) => Math.round(c * 255).toString(16).padStart(2, "0")).join("").toUpperCase();
      if (map[key]) n.fills = [pv(map[key])];
    }
  };
  // Cores das logos -> variáveis (claro) e versão para fundo escuro
  const LIGHT = { "0B2B2A": "ink", "0B7A75": "primary", "FDA333": "accent" };
  const DARK = { "0B2B2A": "surface", "0B7A75": "brand", "FDA333": "accent" };

  // Páginas
  const pageNamed = (name, index) => {
    let p = figma.root.children.find((x) => x.name === name);
    if (!p) { if (index === 0 && figma.root.children.length === 1 && figma.root.children[0].children.length === 0) { p = figma.root.children[0]; p.name = name; } else p = figma.createPage(); p.name = name; }
    return p;
  };
  const pages = ["Logo — exploração", "Cores", "Tipografia", "Padrão e ícones"].map((n, i) => pageNamed(n, i));
  const board = (page, name, width) => {
    for (const c of [...page.children]) if (c.name === name) c.remove();
    const b = AL("VERTICAL", { name, itemSpacing: 40 }); page.appendChild(b);
    b.counterAxisSizingMode = "FIXED"; b.resize(width, 100); b.primaryAxisSizingMode = "AUTO";
    pad(b, 72, 72, 72, 72); b.fills = [pv("background")]; b.cornerRadius = 0; b.x = 0; b.y = 0; return b;
  };

  // -------------------------------------------------------------------------
  // 1. Logo — exploração
  // -------------------------------------------------------------------------
  {
    const b = board(pages[0], "Logo — exploração", 1640);
    const hd = AL("VERTICAL", { itemSpacing: 12 }); fill(b, hd);
    fill(hd, title("Logo — exploração"));
    fill(hd, txt("Doze variações das duas ideias para validação. Cada uma aparece em fundo claro e em fundo escuro. As letras estão em contornos.", 16, "Regular", "textMuted"));
    for (const idea of [1, 2]) {
      const sec = AL("VERTICAL", { name: "Ideia " + idea, itemSpacing: 20 }); fill(b, sec);
      fill(sec, txt(idea === 1 ? "Ideia 1 — Conkat_ em Unageo" : "Ideia 2 — Con em Ahellya + kat_ em Unageo", 22, "Semi Bold"));
      fill(sec, txt(idea === 1
        ? "Unageo (Richard Sepsi), licença SIL Open Font License 1.1: uso comercial em logo permitido."
        : "Ahellya (Dmitry Barsukov): o dafont indica \"100% Free\", mas o arquivo da fonte diz \"All Rights Reserved\". Confirmar a licença com o autor antes de adotar.",
        14, "Regular", idea === 1 ? "textMuted" : "accentText"));
      const grid = figma.createFrame(); grid.name = "Variações"; grid.fills = []; grid.layoutMode = "HORIZONTAL"; grid.layoutWrap = "WRAP";
      grid.itemSpacing = 24; grid.counterAxisSpacing = 24; fill(sec, grid); grid.primaryAxisSizingMode = "FIXED"; grid.counterAxisSizingMode = "AUTO";
      for (const l of DATA.logos.filter((x) => x.idea === idea)) {
        const card = AL("VERTICAL", { name: "Logo " + l.id, itemSpacing: 14 }); card.counterAxisSizingMode = "FIXED"; card.resize(736, 10); card.primaryAxisSizingMode = "AUTO";
        card.fills = [pv("surface")]; card.cornerRadius = 20; pad(card, 20, 20, 20, 20); card.strokes = [pv("border")]; card.strokeWeight = 1; card.strokeAlign = "INSIDE";
        const lab = AL("HORIZONTAL", { itemSpacing: 10 }); lab.counterAxisAlignItems = "CENTER"; fill(card, lab);
        lab.appendChild(txt(l.id, 15, "Bold")); fill(lab, txt(l.name, 14, "Regular", "textMuted"));
        const row = AL("HORIZONTAL", { itemSpacing: 12 }); fill(card, row);
        for (const dark of [false, true]) {
          const box = AL("HORIZONTAL", { name: dark ? "Fundo escuro" : "Fundo claro" }); box.primaryAxisSizingMode = "FIXED"; box.counterAxisSizingMode = "FIXED";
          box.resize(dark ? 268 : 416, 180); box.cornerRadius = 14; box.fills = [pv(dark ? "ink" : "background")]; box.primaryAxisAlignItems = "CENTER"; box.counterAxisAlignItems = "CENTER";
          const n = svgNode(l.svg, dark ? 46 : 70, "Conkat " + l.id + (dark ? " (negativo)" : "")); recolor(n, dark ? DARK : LIGHT); box.appendChild(n);
          row.appendChild(box);
        }
        grid.appendChild(card);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. Cores
  // -------------------------------------------------------------------------
  {
    const b = board(pages[1], "Cores", 1640);
    fill(b, title("Cores"));
    fill(b, txt("Teal é ação; laranja é destaque pontual, sempre com texto escuro. As cores estão salvas como variáveis na coleção \"Conkat / Cores\".", 16, "Regular", "textMuted"));
    const grid = figma.createFrame(); grid.name = "Amostras"; grid.fills = []; grid.layoutMode = "HORIZONTAL"; grid.layoutWrap = "WRAP"; grid.itemSpacing = 20; grid.counterAxisSpacing = 20;
    fill(b, grid); grid.primaryAxisSizingMode = "FIXED"; grid.counterAxisSizingMode = "AUTO";
    for (const [k, h, use] of COLORS) {
      const c = AL("VERTICAL", { name: k }); c.counterAxisSizingMode = "FIXED"; c.resize(280, 10); c.primaryAxisSizingMode = "AUTO";
      c.fills = [pv("surface")]; c.cornerRadius = 16; c.clipsContent = true; c.strokes = [pv("border")]; c.strokeWeight = 1; c.strokeAlign = "INSIDE";
      const sw = figma.createRectangle(); sw.name = "cor"; fill(c, sw); sw.resize(280, 120); sw.fills = [pv(k)];
      const t = AL("VERTICAL", { itemSpacing: 4 }); fill(c, t); pad(t, 14, 16, 16, 16);
      t.appendChild(txt("cor/" + k, 15, "Semi Bold")); t.appendChild(txt(h, 13, "Medium", "textMuted")); fill(t, txt(use, 13, "Regular", "textMuted"));
      grid.appendChild(c);
    }
  }

  // -------------------------------------------------------------------------
  // 3. Tipografia
  // -------------------------------------------------------------------------
  {
    const b = board(pages[2], "Tipografia", 1640);
    fill(b, title("Tipografia"));
    const block = (head, note, noteColor) => { const s = AL("VERTICAL", { itemSpacing: 16 }); fill(b, s); s.fills = [pv("surface")]; s.cornerRadius = 20; pad(s, 28, 32, 32, 32); s.strokes = [pv("border")]; s.strokeWeight = 1; s.strokeAlign = "INSIDE"; fill(s, txt(head, 22, "Semi Bold")); fill(s, txt(note, 14, "Regular", noteColor || "textMuted")); return s; };
    const u = block("Unageo — logo", "Geométrica, de traço uniforme. Licença SIL Open Font License 1.1. Pesos: Light a Black, com itálicos. Exemplos em Regular, Medium e Bold.");
    for (const sv of DATA.specimens.unageo) u.appendChild(svgNode(sv, 46, "Unageo"));
    const a = block("Ahellya — logo (ideia 2)", "Serifada clássica. Licença a confirmar com o autor (o arquivo diz \"All Rights Reserved\"). Exemplos em Regular e Itálico.", "accentText");
    for (const sv of DATA.specimens.ahellya) a.appendChild(svgNode(sv, 46, "Ahellya"));
    const i = block("Interface — Schibsted Grotesk e Inter", "Usadas no site e nos materiais digitais. Schibsted Grotesk nos títulos, Inter no texto corrido.");
    const h1 = txt("Profissionais verificados de Joinville e região.", 40, "SemiBold", "text", "Schibsted Grotesk"); h1.letterSpacing = { unit: "PERCENT", value: -2 }; fill(i, h1);
    fill(i, txt("Manutenção, limpeza, reformas, beleza, aulas, mudanças e outros serviços. Veja preço e avaliações e chame direto no WhatsApp, sem criar conta.", 18, "Regular", "textMuted"));
  }

  // -------------------------------------------------------------------------
  // 4. Padrão e ícones
  // -------------------------------------------------------------------------
  {
    const b = board(pages[3], "Padrão e ícones", 1640);
    fill(b, title("Padrão e ícones"));
    fill(b, txt("O padrão de ícones de serviços é o fundo das telas do app (laranja, traço fino, opacidade 35%). Os ícones de interface são da família Phosphor, estilo regular.", 16, "Regular", "textMuted"));
    // Padrão (mesmo desenho de assets/images/background/conkat-pattern-tile.svg do app)
    const B = DATA.patternBodies;
    let g = ""; for (let r = 0; r < 14; r++) for (let c = 0; c < 14; c++) { const x = (r % 2 ? 48 : 6) + c * 84, y = 27 + r * 84; g += `<g transform="translate(${x} ${y}) scale(1.25)">${B[(c + r) % 14]}</g>`; }
    const pat = figma.createNodeFromSvg(`<svg xmlns="http://www.w3.org/2000/svg" width="1176" height="1176" viewBox="0 0 1176 1176"><g fill="none" stroke="#FDA333" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${g}</g></svg>`);
    pat.name = "Padrão de ícones (tile 1176 × 1176)"; pat.rescale(0.5);
    const holder = figma.createFrame(); holder.name = "Padrão"; holder.resize(588, 588); holder.cornerRadius = 20; holder.fills = [pv("background")]; holder.clipsContent = true; holder.appendChild(pat);
    b.appendChild(holder);
    const grid = figma.createFrame(); grid.name = "Ícones"; grid.fills = []; grid.layoutMode = "HORIZONTAL"; grid.layoutWrap = "WRAP"; grid.itemSpacing = 16; grid.counterAxisSpacing = 16;
    fill(b, grid); grid.primaryAxisSizingMode = "FIXED"; grid.counterAxisSizingMode = "AUTO";
    for (const [k, body] of Object.entries(DATA.icons)) {
      const c = AL("VERTICAL", { name: k, itemSpacing: 8 }); c.counterAxisAlignItems = "CENTER"; c.counterAxisSizingMode = "FIXED"; c.resize(120, 10); c.primaryAxisSizingMode = "AUTO";
      c.fills = [pv("surface")]; c.cornerRadius = 14; pad(c, 18, 8, 14, 8); c.strokes = [pv("border")]; c.strokeWeight = 1; c.strokeAlign = "INSIDE";
      const n = figma.createNodeFromSvg(`<svg width="32" height="32" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg">${body}</svg>`); n.name = "ícone/" + k;
      for (const p of n.findAll((x) => "fills" in x && Array.isArray(x.fills) && x.fills.length)) p.fills = [pv("ink")];
      c.appendChild(n); c.appendChild(txt(k, 12, "Medium", "textMuted")); grid.appendChild(c);
    }
  }

  await figma.setCurrentPageAsync(pages[0]);
  figma.viewport.scrollAndZoomIntoView(pages[0].children);
  log("Arquivo de marca montado: " + pages.map((p) => p.name).join(", "));
}
